func ModelTraceLoadBody(r *TableReader, value *ModelTrace) bool {
	ModelTraceReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0x4fbdf626b33de6bf: // sourceSha256
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.SourceSha256, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x952f22722a282495: // modelSha256
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
					break
				}
				if elemKind != 13 {
					if !tableKindWidens(elemKind, 13) {
						r.Report.KindMismatch++
						break
					}
					r.Report.Widened++
				}
				slot := (*tableContainer)(unsafe.Pointer(&value.ModelSha256))
				if !tableContainerFill(&sub.Nodes.Carve, slot, count, int64(unsafe.Sizeof(*new(ModelHashRow))), 8) {
					if sub.Nodes.Carve.Refused {
						r.Take(sub)
						return false
					}
					r.Report.Malformed = true
					break
				}
				slot.Count = 0
				for i := uint64(0); i < count; i++ {
					p := (*ModelHashRow)(tableContainerFillAt(&sub.Nodes.Carve, slot, int32(i), int64(unsafe.Sizeof(*new(ModelHashRow)))))
					if p == nil {
						r.Report.Malformed = true
						break
					}
					landed := false
					for once := true; once; once = false {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						ModelHashLoadBody(&elem, p)
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							ModelHashReset(p)
						}
						landed = true
					}
					if !landed {
						if sub.Nodes.Carve.Worker != nil {
							tableContainerErase(sub.Nodes.Carve.Worker.Arena, slot, unsafe.Pointer(p), int64(unsafe.Sizeof(*p)))
						}
						break
					}
					if sub.Nodes.Carve.Worker == nil {
						slot.Count++
					}
				}
				r.Take(sub)
				if r.Nodes.Carve.Refused {
					return false
				}
			}
		case 0x7f5f002d3284b6c3: // initial
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			ModelStateLoadBody(&sub, &value.Initial)
			r.Take(sub)
			if r.Nodes.Carve.Refused {
				return false
			}
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				ModelStateReset(&value.Initial)
			}
		case 0x124250ad5a5b6d14: // steps
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
					break
				}
				if elemKind != 13 {
					if !tableKindWidens(elemKind, 13) {
						r.Report.KindMismatch++
						break
					}
					r.Report.Widened++
				}
				slot := (*tableContainer)(unsafe.Pointer(&value.Steps))
				if !tableContainerFill(&sub.Nodes.Carve, slot, count, int64(unsafe.Sizeof(*new(ModelTraceStepRow))), 8) {
					if sub.Nodes.Carve.Refused {
						r.Take(sub)
						return false
					}
					r.Report.Malformed = true
					break
				}
				slot.Count = 0
				for i := uint64(0); i < count; i++ {
					p := (*ModelTraceStepRow)(tableContainerFillAt(&sub.Nodes.Carve, slot, int32(i), int64(unsafe.Sizeof(*new(ModelTraceStepRow)))))
					if p == nil {
						r.Report.Malformed = true
						break
					}
					landed := false
					for once := true; once; once = false {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						ModelTraceStepLoadBody(&elem, p)
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							ModelTraceStepReset(p)
						}
						landed = true
					}
					if !landed {
						if sub.Nodes.Carve.Worker != nil {
							tableContainerErase(sub.Nodes.Carve.Worker.Arena, slot, unsafe.Pointer(p), int64(unsafe.Sizeof(*p)))
						}
						break
					}
					if sub.Nodes.Carve.Worker == nil {
						slot.Count++
					}
				}
				r.Take(sub)
				if r.Nodes.Carve.Refused {
					return false
				}
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

