type ModelTraceBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ModelTraceBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ModelTrace{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ModelTraceReset((*ModelTrace)(p))
	return true
}
func (b *ModelTraceBuilder) GetRoot() *ModelTrace {
	if b.Arena.Locked {
		return nil
	}
	return (*ModelTrace)(b.Arena.At(b.root))
}
func (b *ModelTraceBuilder) AsConst() *ModelTrace {
	if len(b.region) == 0 {
		return nil
	}
	return (*ModelTrace)(unsafe.Pointer(&b.region[0]))
}
func (b *ModelTraceBuilder) Region() []byte { return b.region }
func (b *ModelTraceBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ModelTraceTableType(), &b.Arena)
}
func (b *ModelTraceBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ModelTraceTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ModelTraceBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ModelTraceTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ModelTraceBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
